class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        OFFSET = 2000
        MAX_SUM = 4000
        # dp0[s] stores max product for sum s (index s+OFFSET) with even length
        # dp1[s] stores max product for sum s (index s+OFFSET) with odd length
        dp0 = [-1] * MAX_SUM
        dp1 = [-1] * MAX_SUM

        for x in nums:
            # Copy current state
            new_dp0 = dp0[:]
            new_dp1 = dp1[:]

            # 1. Start a new subsequence with x
            # Length 1 (odd), sum x
            if x <= limit:
                idx = x + OFFSET
                if 0 <= idx < MAX_SUM:
                    if new_dp1[idx] < x:
                        new_dp1[idx] = x

            # 2. Extend existing subsequences
            # Iterate over all possible sums
            for s in range(MAX_SUM):
                # Check dp0 (even length) -> add x -> new sum s + x -> odd length
                val0 = dp0[s]
                if val0 != -1:
                    ns = s + x
                    if ns < MAX_SUM:
                        prod = val0 * x
                        if prod <= limit:
                            if new_dp1[ns] < prod:
                                new_dp1[ns] = prod

                # Check dp1 (odd length) -> sub x -> new sum s - x -> even length
                val1 = dp1[s]
                if val1 != -1:
                    ns = s - x
                    if ns >= 0:
                        prod = val1 * x
                        if prod <= limit:
                            if new_dp0[ns] < prod:
                                new_dp0[ns] = prod

            dp0 = new_dp0
            dp1 = new_dp1

        idx = k + OFFSET
        if 0 <= idx < MAX_SUM:
            res = dp0[idx]
            if dp1[idx] > res:
                res = dp1[idx]
            return res if res != -1 else -1
        return -1

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def solve(n):
            if n == 0: return 0
            digits = list(map(int, str(n)))
            length = len(digits)
            max_s = 9 * length
            total_count = 0

            # Precompute digits

            for s in range(1, max_s + 1):
                memo = {}

                # We can use a stack for iterative DP to avoid recursion overhead?
                # But recursion is easier.

                # To speed up, we can use a list for memo if state space is dense?
                # But it's sparse.

                # Let's use recursion with memo.

                # Optimization: pass s as closure variable

                def dp(idx, tight, current_sum, current_prod):
                    # current_prod is modulo s

                    # State key
                    # tight is bool, convert to int
                    state = (idx, tight, current_sum, current_prod)
                    if state in memo:
                        return memo[state]

                    if current_sum > s:
                        return 0

                    if idx == length:
                        if current_sum == s and current_prod == 0:
                            return 1
                        return 0

                    limit = digits[idx] if tight else 9
                    res = 0

                    # Iterate digits
                    # If tight is False, limit is 9.
                    # We can unroll or just loop.

                    for d in range(0, limit + 1):
                        new_tight = tight and (d == limit)
                        new_sum = current_sum + d

                        if new_sum > s:
                            continue

                        new_prod = current_prod

                        if current_sum == 0:
                            if d == 0:
                                new_prod = 1 % s
                            else:
                                new_prod = d % s
                        else:
                            new_prod = (current_prod * d) % s

                        res += dp(idx + 1, new_tight, new_sum, new_prod)

                    memo[state] = res
                    return res

                total_count += dp(0, True, 0, 1 % s)

            return total_count

        return solve(r) - solve(l - 1)

