class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        if not words:
            return []

        root = TrieNode()
        root.depth = 0
        all_nodes = [root]

        # Build Trie
        for word in words:
            node = root
            for char in word:
                if char not in node.children:
                    new_node = TrieNode()
                    new_node.parent = node
                    new_node.depth = node.depth + 1
                    new_node.char_from_parent = char
                    node.children[char] = new_node
                    all_nodes.append(new_node)
                node = node.children[char]
                node.count += 1

        # Find max depth with count >= k
        best_depth = -1
        best_nodes = []

        for node in all_nodes:
            if node.count >= k:
                if node.depth > best_depth:
                    best_depth = node.depth
                    best_nodes = [node]
                elif node.depth == best_depth:
                    best_nodes.append(node)

        # If no node found (should not happen as root count >= k)
        if best_depth == -1:
            return [0] * len(words)

        # If multiple nodes at best_depth
        if len(best_nodes) > 1:
            return [best_depth] * len(words)

        # Unique node at best_depth
        u_star = best_nodes[0]

        if u_star.count > k:
            return [best_depth] * len(words)

        # u_star.count == k
        # Compute Val

        # Mark ancestors of u_star
        ancestors = set()
        curr = u_star
        while curr:
            ancestors.add(curr)
            curr = curr.parent

        D_second = -1
        D_ancestor = -1

        for node in all_nodes:
            if node == u_star:
                continue
            if node.count < k:
                continue

            if node in ancestors:
                if node.count >= k + 1:
                    if node.depth > D_ancestor:
                        D_ancestor = node.depth
            else:
                if node.depth > D_second:
                    D_second = node.depth

        Val = max(D_second, D_ancestor)
        if Val == -1:
            Val = 0

        # Reconstruct prefix of u_star
        prefix_chars = []
        curr = u_star
        while curr.parent:
            prefix_chars.append(curr.char_from_parent)
            curr = curr.parent
        prefix_str = "".join(reversed(prefix_chars))

        ans = [0] * len(words)

        for i, word in enumerate(words):
            if word.startswith(prefix_str):
                ans[i] = Val
            else:
                ans[i] = best_depth

        return ans

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1

        W = [None] * L
        is_fixed = [False] * L

        # Step 1: Apply T constraints
        for i in range(n):
            if str1[i] == 'T':
                for k in range(m):
                    pos = i + k
                    char = str2[k]
                    if W[pos] is not None and W[pos] != char:
                        return ""
                    W[pos] = char
                    is_fixed[pos] = True

        # Step 2: Fill with 'a'
        for i in range(L):
            if W[i] is None:
                W[i] = 'a'

        # Step 3: Check F constraints
        for i in range(n):
            if str1[i] == 'F':
                # Check if W[i : i+m] == str2
                # Using a loop for efficiency
                match = True
                for k in range(m):
                    if W[i+k] != str2[k]:
                        match = False
                        break

                if match:
                    # Fix: change rightmost non-fixed to 'b'
                    # Search backwards
                    fixed_found = False
                    for p in range(i + m - 1, i - 1, -1):
                        if not is_fixed[p]:
                            W[p] = 'b'
                            fixed_found = True
                            break
                    if not fixed_found:
                        return ""

        return "".join(W)

