class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)

        def count_pairs(A, B, M):
            # Counts pairs (x, y) such that 0 <= x <= A, 0 <= y <= B, x + y <= M
            if M < 0:
                return 0
            if M >= A + B:
                return (A + 1) * (B + 1)

            x_lim = min(A, M)
            x_split = M - B

            # Range 1: x <= x_split => min(B, M-x) = B
            end1 = min(x_lim, x_split)
            cnt1 = max(0, end1 + 1)
            sum1 = cnt1 * (B + 1)

            # Range 2: x > x_split => min(B, M-x) = M - x
            start2 = max(0, x_split + 1)
            if start2 > x_lim:
                sum2 = 0
            else:
                cnt2 = x_lim - start2 + 1
                first = M - start2 + 1
                last = M - x_lim + 1
                sum2 = cnt2 * (first + last) // 2

            return sum1 + sum2

        # Calculate sum of maximums
        max_sum = 0
        l_max = [-1] * n
        r_max = [n] * n
        stack = []
        for i in range(n):
            while stack and nums[stack[-1]] < nums[i]:
                stack.pop()
            if stack:
                l_max[i] = stack[-1]
            stack.append(i)

        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            if stack:
                r_max[i] = stack[-1]
            stack.append(i)

        for i in range(n):
            A = i - l_max[i] - 1
            B = r_max[i] - i - 1
            max_sum += nums[i] * count_pairs(A, B, k - 1)

        # Calculate sum of minimums
        min_sum = 0
        l_min = [-1] * n
        r_min = [n] * n
        stack = []
        for i in range(n):
            while stack and nums[stack[-1]] > nums[i]:
                stack.pop()
            if stack:
                l_min[i] = stack[-1]
            stack.append(i)

        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] >= nums[i]:
                stack.pop()
            if stack:
                r_min[i] = stack[-1]
            stack.append(i)

        for i in range(n):
            A = i - l_min[i] - 1
            B = r_min[i] - i - 1
            min_sum += nums[i] * count_pairs(A, B, k - 1)

        return max_sum + min_sum

