class Solution:
    def longestSpecialPath(self, edges: List[List[int]], nums: List[int]) -> List[int]:
        n = len(nums)
        adj = [[] for _ in range(n)]
        for u, v, w in edges:
            adj[u].append((v, w))
            adj[v].append((u, w))

        dists = [0] * n
        last_occ = {}
        path = []
        res = [0, 1]

        def dfs(u, p, current_dist, current_depth, min_start_idx):
            val = nums[u]

            prev_idx = last_occ.get(val, -1)
            last_occ[val] = current_depth

            new_min_start = min_start_idx
            if prev_idx != -1:
                if prev_idx + 1 > new_min_start:
                    new_min_start = prev_idx + 1

            path.append(u)
            dists[u] = current_dist

            start_node = path[new_min_start]
            path_len = current_dist - dists[start_node]
            num_nodes = current_depth - new_min_start + 1

            if path_len > res[0]:
                res[0] = path_len
                res[1] = num_nodes
            elif path_len == res[0]:
                if num_nodes < res[1]:
                    res[1] = num_nodes

            for v, w in adj[u]:
                if v != p:
                    dfs(v, u, current_dist + w, current_depth + 1, new_min_start)

            path.pop()
            if prev_idx == -1:
                del last_occ[val]
            else:
                last_occ[val] = prev_idx

        dfs(0, -1, 0, 0, 0)
        return res

