        # B^2 = N * J (all 1s matrix scaled by N)
        # Modulo 2, this is (N % 2) * J
        val = N % 2
        for _ in range(N):
            print(" ".join([str(val)] * N))
        return

    # Count zeros
    K = 0
    for r in range(N):
        for c in range(N):
            if A[r][c] == 0:
                K += 1

    # Factor (-1)^K mod p
    if K % 2 == 1:
        F = p - 1
    else:
        F = 1

    # Matrix multiplication function
    def mat_mul(X, Y, mod, n):
        # X and Y are n x n matrices
        # Returns X * Y % mod
        # Optimized: i, k, j order, deferred modulo
        Z = [[0] * n for _ in range(n)]
        for i in range(n):
            row_x = X[i]
            row_z = Z[i]
            for k in range(n):
                val = row_x[k]
                if val == 0:
                    continue
                row_y = Y[k]
                for j in range(n):
                    row_z[j] += val * row_y[j]
            # Apply modulo after processing all k for this row
            for j in range(n):
                row_z[j] %= mod
        return Z

    # Matrix exponentiation: A^p
    # Binary exponentiation
    # Result = I
    # Base = A
    # Exp = p

    # Identity matrix
    res = [[0] * N for _ in range(N)]
    for i in range(N):
        res[i][i] = 1

    base = A
    exp = p

    while exp > 0:
        if exp % 2 == 1:
            res = mat_mul(res, base, p, N)
        base = mat_mul(base, base, p, N)
        exp //= 2

    # res is A^p
    # Multiply by F
    for i in range(N):
        for j in range(N):
            res[i][j] = (res[i][j] * F) % p

    # Type 2 corrections
    # Iterate over all zero edges
    # We can collect zero edges first to avoid nested loops over A
    zero_edges = []
    for r in range(N):
        for c in range(N):
            if A[r][c] == 0:
                zero_edges.append((r, c))

    for u, v in zero_edges:
        if u == v:
            # Self-loop zero edge at u
            # Add to Ans[u][j] for j != u if A[u][j] != 0
            # Add to Ans[i][u] for i != u if A[i][u] != 0

            # Optimization: iterate only non-zero entries?
            # But A is small, just iterate.

            # Row u
            row_u = A[u]
            res_row_u = res[u]
            for j in range(N):
                if j != u and row_u[j] != 0:
                    val = (res_row_u[j] + F * row_u[j]) % p
                    res_row_u[j] = val

            # Column u
            # We need to access A[i][u] and res[i][u]
            # Iterate i
            for i in range(N):
                if i != u:
                    val_aiu = A[i][u]
                    if val_aiu != 0:
                        val_res = (res[i][u] + F * val_aiu) % p
                        res[i][u] = val_res
        else:
            # u != v
            if p == 3:
                # Check if A[v][u] != 0
                val_vu = A[v][u]
                if val_vu != 0:
                    val_res = (res[u][v] + F * val_vu) % p
                    res[u][v] = val_res

    # Print result
    for i in range(N):
        print(" ".join(map(str, res[i])))

